/**
 * Turning touches on the full-screen picture into commands.
 *
 * The YouTube frame swallows every touch that lands on it, so the gestures live on a
 * transparent sheet laid over the top. That sheet only exists while a slot is full screen;
 * the rest of the time the frame belongs to YouTube, controls and all.
 *
 * All the arithmetic is in `gesture-math.ts` and tested there. What is left here is the
 * bookkeeping that cannot be tested without a browser: which fingers are down, whether a run
 * of taps has finished, and where the current drag started.
 */

import type { DragKind } from './gesture-math.js';
import {
  dismissIntent,
  lockedDragKind,
  neighbourIntent,
  pinchIntent,
  seekSecondsFor,
  sideOf,
  speedStepsFor,
  volumeFor,
} from './gesture-math.js';

/**
 * How long a run of taps stays open for another one, and so how long a single tap waits
 * before it plays or pauses.
 *
 * It was the other way round between 2026-09-21 and 2026-09-22: the first tap acted at once
 * and a second tap took it back. That made a single tap answer in 39ms rather than 260, but
 * every double tap paused the video on its way to the jump, and the flicker was visible.
 * The operator chose the wait over the flicker on 2026-09-22.
 */
const TAP_WINDOW_MS = 320;

export interface GestureHandlers {
  /** A single tap: play or pause. Acted on once no second tap has followed it. */
  readonly onToggle: () => void;
  /** A run of taps: jump by this many seconds, negative for backwards. */
  readonly onSeek: (seconds: number) => void;
  /** A sideways drag, in whole speed steps since the drag began. */
  readonly onSpeedStep: (steps: number) => void;
  /** An upward or downward drag. Called with the volume the finger is currently pointing at. */
  readonly onVolume: (volume: number) => void;
  /** A squeeze or a spread. */
  readonly onFit: (mode: 'fill' | 'fit') => void;
  /** Two fingers tapped at once. */
  readonly onTwoFingerTap: () => void;
  /** Three fingers tapped at once. */
  readonly onThreeFingerTap: () => void;
  /** Two fingers travelled down the glass together: leave full screen. */
  readonly onDismiss: () => void;
  /** Three fingers swept sideways: show the slot before or after this one. */
  readonly onNeighbour: (direction: 'next' | 'previous') => void;
  /** The volume to start a vertical drag from, read at the moment the finger lands. */
  readonly currentVolume: () => number;
  /**
   * How the picture is sized right now, read when the first finger lands.
   *
   * Needed to undo a squeeze: a third finger means the last two were on their way to being
   * three, and whatever they changed on the way was never asked for.
   */
  readonly currentFit: () => 'fill' | 'fit';
}

interface Point {
  readonly x: number;
  readonly y: number;
}

function distance(a: Point, b: Point): number {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

/**
 * The middle of however many fingers are down. Three fingers never travel as one, so the
 * swipe has to be measured from what they average out to rather than from any one of them.
 */
function centreOf(points: Iterable<Point>): Point {
  let x = 0;
  let y = 0;
  let n = 0;
  for (const point of points) {
    x += point.x;
    y += point.y;
    n += 1;
  }
  return n === 0 ? { x: 0, y: 0 } : { x: x / n, y: y / n };
}

/**
 * Pointer capture keeps a drag alive when the finger wanders off the picture, but it throws
 * for a pointer the browser no longer considers down. Losing capture costs a long drag;
 * letting the error out would cost the gesture entirely.
 */
function capture(sheet: HTMLElement, pointerId: number, hold: boolean): void {
  try {
    if (hold) sheet.setPointerCapture(pointerId);
    else if (sheet.hasPointerCapture(pointerId)) sheet.releasePointerCapture(pointerId);
  } catch {
    // Nothing to do: the gesture still works, it just ends if the finger leaves.
  }
}

/**
 * Starts listening. Returns the function that stops again — the sheet outlives any one
 * full-screen session, so the listeners have to come off with it.
 */
export function attachGestures(sheet: HTMLElement, handlers: GestureHandlers): () => void {
  const active = new Map<number, Point>();

  let startedAt: Point | null = null;
  let startVolume = 0;
  let steppedBy = 0;
  let dragged = false;
  /** Which way this drag is going, fixed the first time it was clear enough to say. */
  let lockedAxis: DragKind | null = null;
  /** Whether a vertical drag has moved the volume away from `startVolume`. */
  let volumeMoved = false;
  let pinchStart = 0;
  /** Set once two fingers have been down together, so the lift is not read as a tap. */
  let multiTouch = false;
  /**
   * Set once a squeeze or spread has been acted on. Without it the lift looks like a
   * two-finger tap: acting on a pinch moves the baseline to wherever the fingers are, so by
   * the time they come up the distance matches the baseline exactly.
   */
  let pinched = false;
  /**
   * Set once three fingers have been down together.
   *
   * Three fingers are two fingers first, for a moment, and a hand on its way to a sideways
   * sweep is already spreading — so without this every three-finger swipe squeezes or spreads
   * the picture on its way in, and taps the mute on its way out.
   */
  let manyTouch = false;
  /** How the picture was sized before this gesture, so a mistaken squeeze can be put back. */
  let startFit: 'fill' | 'fit' = 'fit';
  /** Where the fingers averaged out to when the third one landed. */
  let sweepFrom: Point | null = null;
  /** One neighbour per sweep: a long drag must not run through the whole wall. */
  let sweptAlready = false;
  /** Where the two fingers averaged out to when the second one landed. */
  let twoFrom: Point | null = null;
  /** Set once this gesture has asked to leave full screen; it may only ask once. */
  let dismissed = false;
  /** Set once three fingers lifting have been read as a tap, so they are read as one. */
  let manyTapped = false;

  let taps = 0;
  let tapSide: 'left' | 'right' = 'right';
  let tapTimer: number | null = null;

  /**
   * Puts back whatever a one-finger drag changed before a second finger arrived.
   *
   * Two fingers never land at the same instant. In the milliseconds between them the hand is
   * already moving — that is what a squeeze is — so the first finger alone reads as a
   * sideways or upward drag and starts changing the speed or the volume. Without this, every
   * squeeze leaves a stray speed change behind it.
   */
  const undoOneFingerDrag = (): void => {
    if (steppedBy !== 0) {
      handlers.onSpeedStep(-steppedBy);
      steppedBy = 0;
    }
    if (volumeMoved) {
      handlers.onVolume(startVolume);
      volumeMoved = false;
    }
    dragged = false;
    lockedAxis = null;
  };

  const settleTaps = (): void => {
    tapTimer = null;
    const counted = taps;
    const side = tapSide;
    taps = 0;
    if (counted === 0) return;
    if (counted === 1) {
      handlers.onToggle();
      return;
    }
    const seconds = seekSecondsFor(counted, side);
    if (seconds !== 0) handlers.onSeek(seconds);
  };

  const countTap = (point: Point): void => {
    tapSide = sideOf(point.x - sheet.getBoundingClientRect().left, sheet.clientWidth);
    taps += 1;
    if (tapTimer !== null) window.clearTimeout(tapTimer);
    tapTimer = window.setTimeout(settleTaps, TAP_WINDOW_MS);
  };

  const onDown = (event: PointerEvent): void => {
    capture(sheet, event.pointerId, true);
    active.set(event.pointerId, { x: event.clientX, y: event.clientY });

    if (active.size === 1) {
      startedAt = { x: event.clientX, y: event.clientY };
      startVolume = handlers.currentVolume();
      startFit = handlers.currentFit();
      steppedBy = 0;
      dragged = false;
      lockedAxis = null;
      volumeMoved = false;
      multiTouch = false;
      pinched = false;
      manyTouch = false;
      sweepFrom = null;
      sweptAlready = false;
      twoFrom = null;
      dismissed = false;
      manyTapped = false;
      return;
    }

    multiTouch = true;
    if (active.size === 2) {
      undoOneFingerDrag();
      const [a, b] = [...active.values()];
      pinchStart = a && b ? distance(a, b) : 0;
      twoFrom = centreOf(active.values());
      // A run of single taps is not what two fingers meant; drop whatever was counted.
      taps = 0;
      if (tapTimer !== null) {
        window.clearTimeout(tapTimer);
        tapTimer = null;
      }
      return;
    }

    if (active.size === 3) {
      manyTouch = true;
      // Whatever the two-finger stage changed on its way here was never asked for.
      if (pinched) {
        handlers.onFit(startFit);
        pinched = false;
      }
      sweepFrom = centreOf(active.values());
      sweptAlready = false;
    }
  };

  const onMove = (event: PointerEvent): void => {
    if (!active.has(event.pointerId)) return;
    active.set(event.pointerId, { x: event.clientX, y: event.clientY });

    // Three fingers or more: a sideways sweep, and nothing else. Squeezing is off from the
    // moment a third finger arrives and stays off until the hand leaves the glass, so a sweep
    // that loses a finger part way through does not turn into a squeeze on its way out.
    if (manyTouch) {
      if (sweepFrom === null || sweptAlready || active.size < 3) return;
      const centre = centreOf(active.values());
      const direction = neighbourIntent(centre.x - sweepFrom.x, centre.y - sweepFrom.y);
      if (direction !== 'none') {
        sweptAlready = true;
        handlers.onNeighbour(direction);
      }
      return;
    }

    if (active.size === 2) {
      const [a, b] = [...active.values()];
      if (a === undefined || b === undefined || pinchStart <= 0) return;
      const intent = pinchIntent(distance(a, b) / pinchStart);
      if (intent !== 'none') {
        pinched = true;
        handlers.onFit(intent);
        // Acting once per squeeze: reset the baseline so it does not fire every frame.
        pinchStart = distance(a, b);
        return;
      }
      /*
       * Two fingers going down together. Checked only after the squeeze has declined, so a
       * hand that is pinching while also drifting downwards keeps pinching — the distance
       * between the fingers is the deliberate part of that gesture, and the drift is not.
       */
      if (twoFrom === null || dismissed) return;
      const centre = centreOf(active.values());
      if (dismissIntent(centre.x - twoFrom.x, centre.y - twoFrom.y)) {
        dismissed = true;
        handlers.onDismiss();
      }
      return;
    }

    /*
     * One finger left of two is still part of a two-finger gesture, not the start of a new
     * one-finger drag. Fingers come off a squeeze one at a time, and the survivor is far from
     * where the first finger landed — so without this it reads as a long drag and throws the
     * speed or the volume across the screen at the exact moment the operator is letting go.
     * Nothing one-fingered happens again until the hand is off the glass entirely.
     */
    if (startedAt === null || multiTouch) return;
    const dx = event.clientX - startedAt.x;
    const dy = event.clientY - startedAt.y;
    // Decided once, then held until the hand comes off the glass — see `lockedDragKind`.
    lockedAxis = lockedDragKind(lockedAxis, dx, dy);
    if (lockedAxis === null) return;
    dragged = true;

    if (lockedAxis === 'horizontal') {
      const steps = speedStepsFor(dx);
      if (steps !== steppedBy) {
        handlers.onSpeedStep(steps - steppedBy);
        steppedBy = steps;
      }
      return;
    }

    volumeMoved = true;
    handlers.onVolume(volumeFor(startVolume, dy, sheet.clientHeight));
  };

  const onUp = (event: PointerEvent): void => {
    const point = active.get(event.pointerId);
    const wasTwo = active.size === 2;
    const wasThree = active.size === 3;
    active.delete(event.pointerId);
    capture(sheet, event.pointerId, false);

    /*
     * Three fingers that arrived, did nothing and left again. `pinched` is false here even
     * when the two-finger stage squeezed on the way in, because the third finger put that
     * back — which is exactly the case this has to accept, since three fingers always land
     * as two first.
     */
    if (wasThree && !manyTapped && !dragged && !pinched && !sweptAlready && !dismissed) {
      manyTapped = true;
      handlers.onThreeFingerTap();
    }

    // `manyTouch` rules the two-finger tap out: three fingers lifting pass through two.
    if (wasTwo && !manyTouch && !dragged && !pinched && !dismissed && pinchStart > 0) {
      const [a, b] = [...active.values(), point];
      if (a !== undefined && b !== undefined && Math.abs(distance(a, b) - pinchStart) < 24) {
        handlers.onTwoFingerTap();
      }
    }

    if (active.size > 0) return;

    if (!dragged && !multiTouch && point !== undefined) countTap(point);
    startedAt = null;
    pinchStart = 0;
  };

  const onCancel = (event: PointerEvent): void => {
    active.delete(event.pointerId);
    if (active.size === 0) {
      startedAt = null;
      pinchStart = 0;
    }
  };

  sheet.addEventListener('pointerdown', onDown);
  sheet.addEventListener('pointermove', onMove);
  sheet.addEventListener('pointerup', onUp);
  sheet.addEventListener('pointercancel', onCancel);

  return () => {
    sheet.removeEventListener('pointerdown', onDown);
    sheet.removeEventListener('pointermove', onMove);
    sheet.removeEventListener('pointerup', onUp);
    sheet.removeEventListener('pointercancel', onCancel);
    if (tapTimer !== null) window.clearTimeout(tapTimer);
    active.clear();
  };
}
