/**
 * Playback speed, per slot.
 *
 * The player accepts a small fixed set and silently ignores anything else, so every stored
 * value, every menu choice and every gesture funnels through here. A rate that never took
 * effect is worse than one that was refused: the slot would keep showing a speed it is not
 * playing at.
 */

export const NORMAL_SPEED = 1;

/** The rates YouTube offers in its own menu, in order. */
export const PLAYBACK_RATES = [0.25, 0.5, 0.75, 1, 1.25, 1.5, 1.75, 2] as const;

export function clampSpeed(value: number): number {
  if (!Number.isFinite(value)) return NORMAL_SPEED;
  // Snap to the nearest offered rate rather than refusing: a stored 1.2 from an older
  // version, or a gesture that landed between two steps, should still mean something.
  let best: number = NORMAL_SPEED;
  let distance = Number.POSITIVE_INFINITY;
  for (const rate of PLAYBACK_RATES) {
    const gap = Math.abs(rate - value);
    if (gap < distance) {
      best = rate;
      distance = gap;
    }
  }
  return best;
}

/** One step along the list, stopping at each end rather than wrapping around. */
export function stepSpeed(value: number, direction: number): number {
  const current = PLAYBACK_RATES.indexOf(clampSpeed(value) as (typeof PLAYBACK_RATES)[number]);
  const next = Math.min(PLAYBACK_RATES.length - 1, Math.max(0, current + Math.sign(direction)));
  return PLAYBACK_RATES[next] as number;
}

/** `1` and `1.5` rather than `1.0` and `1.50` — the label sits in a very small button. */
export function describeSpeed(value: number): string {
  return `${String(clampSpeed(value))}倍`;
}
