/**
 * Build-time configuration.
 *
 * The client id sits in source rather than in a .env file on purpose. Vite inlines every
 * VITE_* value into the bundle anyway, so a .env would hide it from the repository while
 * publishing it to every visitor — the worst of both. Google states plainly that an OAuth
 * client id is not a secret: it identifies the app, and the origin allowlist is what actually
 * restricts who may use it. The real secret (the client secret) is never used here; the app
 * asks for tokens straight from the browser and no server of ours ever sees one.
 *
 * Project: yt-dual-yamaga, owned by yamaga101 (rules/security.md §7).
 */

export const GOOGLE_CLIENT_ID =
  '571236494235-rlcos2oqu0o3cmcqr2mnlic3dss7gt22.apps.googleusercontent.com';

/** Read-only. The app can list what the operator has; it can never change or delete any of it. */
export const YOUTUBE_SCOPE = 'https://www.googleapis.com/auth/youtube.readonly';
