/**
 * The slice of the official IFrame Player API this app actually calls.
 *
 * Hand-written rather than pulled from a package: the surface is small, and writing it out
 * keeps the app honest about what it depends on. Nothing here reaches past the public API —
 * no stream extraction, no ad handling (ADR-0001 Decision 2).
 */

export const PLAYER_STATE = {
  unstarted: -1,
  ended: 0,
  playing: 1,
  paused: 2,
  buffering: 3,
  cued: 5,
} as const;

export type PlayerStateCode = (typeof PLAYER_STATE)[keyof typeof PLAYER_STATE];

export interface YouTubePlayer {
  loadVideoById(videoId: string): void;
  cueVideoById(videoId: string): void;
  playVideo(): void;
  pauseVideo(): void;
  stopVideo(): void;
  mute(): void;
  unMute(): void;
  isMuted(): boolean;
  setVolume(volume: number): void;
  getVolume(): number;
  setPlaybackRate(rate: number): void;
  getPlaybackRate(): number;
  seekTo(seconds: number, allowSeekAhead: boolean): void;
  getPlayerState(): number;
  getCurrentTime(): number;
  getDuration(): number;
  destroy(): void;
}

export interface PlayerReadyEvent {
  readonly target: YouTubePlayer;
}

export interface PlayerStateChangeEvent {
  readonly target: YouTubePlayer;
  readonly data: number;
}

export interface PlayerErrorEvent {
  readonly target: YouTubePlayer;
  readonly data: number;
}

export interface PlayerVars {
  readonly playsinline?: 0 | 1;
  readonly enablejsapi?: 0 | 1;
  readonly rel?: 0 | 1;
  readonly origin?: string;
}

export interface PlayerOptions {
  readonly host?: string;
  readonly videoId?: string;
  readonly playerVars?: PlayerVars;
  readonly events?: {
    readonly onReady?: (event: PlayerReadyEvent) => void;
    readonly onStateChange?: (event: PlayerStateChangeEvent) => void;
    readonly onError?: (event: PlayerErrorEvent) => void;
  };
}

export interface YouTubeNamespace {
  readonly Player: new (element: HTMLElement | string, options: PlayerOptions) => YouTubePlayer;
}

declare global {
  interface Window {
    YT?: YouTubeNamespace;
    onYouTubeIframeAPIReady?: () => void;
  }
}
