/**
 * One playback slot: an official player plus the settings the app keeps for it.
 *
 * Two of these run side by side and both stay audible — that is the whole product
 * (ADR-0001). Nothing here coordinates the two; a slot never mutes or pauses its neighbour,
 * because the pair being independent is exactly what the user asked for.
 */

import { NORMAL_SPEED, clampSpeed } from '../core/speed.js';
import { clampVolume } from '../core/volume.js';
import { loadIframeApi } from './api.js';
import { PLAYER_STATE, type PlayerOptions, type YouTubePlayer } from './types.js';

export type SlotStatus = 'loading' | 'empty' | 'ready' | 'playing' | 'paused' | 'ended' | 'error';

export interface SlotCallbacks {
  readonly onStatusChange: (status: SlotStatus) => void;
  /**
   * The API's raw numeric reason for a refusal, passed through without interpretation.
   * Guessing at what the player meant, instead of reading what it said, cost a full day
   * of wrong conclusions on 2026-09-13. The number goes on screen.
   */
  readonly onError: (code: number) => void;
}

function statusFromCode(code: number): SlotStatus {
  switch (code) {
    case PLAYER_STATE.playing:
      return 'playing';
    case PLAYER_STATE.paused:
      return 'paused';
    case PLAYER_STATE.ended:
      return 'ended';
    case PLAYER_STATE.buffering:
      return 'loading';
    case PLAYER_STATE.cued:
    case PLAYER_STATE.unstarted:
      return 'ready';
    default:
      return 'ready';
  }
}

export interface SlotInitial {
  readonly volume: number;
  readonly speed: number;
  readonly loop: boolean;
}

export class Slot {
  private player: YouTubePlayer | null = null;
  private volume: number;
  private speed: number;
  private looping: boolean;
  private muted = false;
  private pendingVideoId: string | null = null;

  constructor(
    private readonly mount: HTMLElement,
    initial: SlotInitial,
    private readonly callbacks: SlotCallbacks,
  ) {
    this.volume = clampVolume(initial.volume);
    this.speed = clampSpeed(initial.speed);
    this.looping = initial.loop;
  }

  /** Build the player. Resolves once YouTube reports it is ready to take commands. */
  async start(initialVideoId: string | null): Promise<void> {
    const namespace = await loadIframeApi();

    await new Promise<void>((resolve) => {
      const options: PlayerOptions = {
        host: 'https://www.youtube.com',
        playerVars: {
          playsinline: 1,
          enablejsapi: 1,
          rel: 0,
          origin: window.location.origin,
        },
        events: {
          onReady: (event) => {
            this.player = event.target;
            this.player.setVolume(this.volume);
            if (this.speed !== NORMAL_SPEED) this.player.setPlaybackRate(this.speed);
            if (this.pendingVideoId !== null) this.player.cueVideoById(this.pendingVideoId);
            this.callbacks.onStatusChange(this.pendingVideoId === null ? 'empty' : 'ready');
            resolve();
          },
          onStateChange: (event) => {
            // Looping is the default: a slot that falls silent at the end of its video stops
            // being a slot, and with twenty of them nobody is watching for the one that ended.
            if (event.data === PLAYER_STATE.ended && this.looping) {
              event.target.seekTo(0, true);
              event.target.playVideo();
              return;
            }
            this.callbacks.onStatusChange(statusFromCode(event.data));
          },
          onError: (event) => {
            this.callbacks.onError(event.data);
            this.callbacks.onStatusChange('error');
          },
        },
        ...(initialVideoId === null ? {} : { videoId: initialVideoId }),
      };
      this.pendingVideoId = initialVideoId;
      new namespace.Player(this.mount, options);
    });
  }

  get videoId(): string | null {
    return this.pendingVideoId;
  }

  /** Load without playing. The user starts playback themselves, by design. */
  cue(videoId: string): void {
    this.pendingVideoId = videoId;
    this.player?.cueVideoById(videoId);
  }

  play(): void {
    this.player?.playVideo();
  }

  isPlaying(): boolean {
    return this.player?.getPlayerState() === PLAYER_STATE.playing;
  }

  pause(): void {
    this.player?.pauseVideo();
  }

  setVolume(value: number): number {
    this.volume = clampVolume(value);
    this.player?.setVolume(this.volume);
    return this.volume;
  }

  getVolume(): number {
    return this.volume;
  }

  /** Returns the rate that was actually applied, which may be a snapped one. */
  setSpeed(value: number): number {
    this.speed = clampSpeed(value);
    this.player?.setPlaybackRate(this.speed);
    return this.speed;
  }

  getSpeed(): number {
    return this.speed;
  }

  setLooping(looping: boolean): void {
    this.looping = looping;
  }

  isLooping(): boolean {
    return this.looping;
  }

  /** Moves by `seconds`, forwards or back, staying inside the video. */
  nudge(seconds: number): void {
    const player = this.player;
    if (player === null) return;
    const target = Math.max(0, player.getCurrentTime() + seconds);
    const duration = player.getDuration();
    // A duration of 0 means the player does not know yet; seeking to the end would be worse
    // than seeking a little too far, which the player clamps for us.
    player.seekTo(duration > 0 ? Math.min(target, duration) : target, true);
  }

  setMuted(muted: boolean): void {
    this.muted = muted;
    if (muted) this.player?.mute();
    else this.player?.unMute();
  }

  isMuted(): boolean {
    return this.muted;
  }
}
