/**
 * What a finger movement means. Pure arithmetic, no DOM.
 *
 * Gestures are invisible: nothing on screen says that dragging sideways changes the speed, so
 * getting the thresholds wrong is not a cosmetic problem — it is the difference between a
 * control that works and one the operator concludes is broken. Keeping the decisions here,
 * away from the pointer plumbing, is what makes them testable at all.
 */

import { MAX_VOLUME, MIN_VOLUME } from '../core/volume.js';

/**
 * Below this, a finger that moved is still a tap. Thumbs are never perfectly still: a thumb
 * covers something like 40 pixels of glass, and it rolls as it lifts. Set this too tight and
 * an ordinary tap is read as a drag, which does not play or pause — it quietly changes the
 * volume instead, and the tap looks like it was ignored.
 */
export const TAP_SLOP_PX = 24;

/** How far sideways one speed step costs. Roughly a thumb's width on a phone. */
export const SPEED_STEP_PX = 64;

/**
 * Taps beyond the first jump through the video. The first tap plays or pauses instead.
 *
 * Operator, 2026-09-21: three taps 20 seconds, four taps 30. The steps used to triple each
 * time (10/30/60), which made the difference between three and four taps larger than most
 * of what anyone wants to skip.
 */
const SEEK_SECONDS = [10, 20, 30] as const;

/**
 * How far the intended direction must beat the other one before a drag counts.
 *
 * At 1.5 a drag has to stay inside about 34 degrees of level or upright; between 34 and 56
 * degrees nothing happens at all. That dead wedge is the point, and the operator asked for it
 * on 2026-09-22: until then the larger movement simply won, so a drag at 46 degrees — which
 * the hand cannot tell apart from one at 44 — changed the volume instead of the speed. One
 * gesture silently becoming the other is worse than neither of them firing, because the
 * wrong one has already happened by the time it is noticed.
 */
const AXIS_DOMINANCE = 1.5;

export type DragKind = 'horizontal' | 'vertical' | 'none';

/**
 * Which way the finger is going, or nothing when it is going neither way clearly.
 */
export function classifyDrag(dx: number, dy: number): DragKind {
  const across = Math.abs(dx);
  const down = Math.abs(dy);
  if (across <= TAP_SLOP_PX && down <= TAP_SLOP_PX) return 'none';
  if (across >= down * AXIS_DOMINANCE) return 'horizontal';
  if (down >= across * AXIS_DOMINANCE) return 'vertical';
  return 'none';
}

/**
 * The axis a drag is on: whatever it was already on, or the first clear answer.
 *
 * Re-deciding this on every move is what made a drag change the speed and then silently
 * switch to changing the volume — a thumb pivoting from a knuckle curves on its own, and
 * rejecting the diagonal in the middle does not help, because the hand crosses the dead
 * wedge and comes out the far side looking like a clean drag along the other axis.
 * Answering `null` means nothing is decided yet and the caller should leave both alone.
 */
export function lockedDragKind(locked: DragKind | null, dx: number, dy: number): DragKind | null {
  if (locked !== null) return locked;
  const kind = classifyDrag(dx, dy);
  return kind === 'none' ? null : kind;
}

/** Whole speed steps earned by a sideways drag, right for faster. */
export function speedStepsFor(dx: number): number {
  if (!Number.isFinite(dx)) return 0;
  // `|| 0` turns a leftward drag that earned nothing from -0 into 0, so callers comparing
  // against a previous count of 0 are not left wondering why two zeroes differ.
  return Math.trunc(dx / SPEED_STEP_PX) || 0;
}

/**
 * The volume a vertical drag lands on. Up is louder, and dragging the full height of the
 * picture covers the whole range — so the gesture means the same thing on any screen.
 */
export function volumeFor(startVolume: number, dy: number, height: number): number {
  if (!Number.isFinite(dy) || !Number.isFinite(height) || height <= 0) return startVolume;
  const moved = (-dy / height) * (MAX_VOLUME - MIN_VOLUME);
  return Math.min(MAX_VOLUME, Math.max(MIN_VOLUME, Math.round(startVolume + moved)));
}

/**
 * How far a run of taps jumps, negative for backwards. One tap is not a jump — it plays or
 * pauses — so it answers 0, and so does anything that is not a tap at all.
 */
export function seekSecondsFor(taps: number, side: 'left' | 'right'): number {
  if (taps < 2) return 0;
  const step = SEEK_SECONDS[Math.min(taps - 2, SEEK_SECONDS.length - 1)] as number;
  return side === 'left' ? -step : step;
}

/** Which half of the picture a point falls in. The midpoint counts as forward. */
export function sideOf(x: number, width: number): 'left' | 'right' {
  return x < width / 2 ? 'left' : 'right';
}

/**
 * What a two-finger squeeze or spread asks for. The dead band in the middle is deliberate:
 * two fingers never land and lift at exactly the same distance apart.
 */
export function pinchIntent(scale: number): 'fill' | 'fit' | 'none' {
  if (!Number.isFinite(scale) || scale <= 0) return 'none';
  if (scale >= 1.15) return 'fill';
  if (scale <= 0.87) return 'fit';
  return 'none';
}

/**
 * How far three fingers travel sideways before the picture changes to a neighbour.
 *
 * Much further than a one-finger drag needs, because three fingers land less tidily and a
 * mistaken neighbour throws away what was being watched — where a mistaken speed step is
 * undone by dragging back.
 */
export const NEIGHBOUR_SWIPE_PX = 90;

export type NeighbourDirection = 'next' | 'previous' | 'none';

/**
 * Which way a three-finger sideways swipe points. Dragging left brings the next slot in from
 * the right, the way a photo album moves — the fingers push the current picture aside.
 */
export function neighbourIntent(dx: number, dy: number): NeighbourDirection {
  if (!Number.isFinite(dx) || !Number.isFinite(dy)) return 'none';
  // A hand sliding down the glass is not choosing a neighbour, however far sideways it drifts.
  if (Math.abs(dx) < NEIGHBOUR_SWIPE_PX || Math.abs(dy) > Math.abs(dx)) return 'none';
  return dx < 0 ? 'next' : 'previous';
}

/**
 * How far two fingers travel down together before full screen is dismissed.
 *
 * As far as the neighbour swipe, and for the same reason: leaving full screen throws away
 * what was being watched, and two fingers sliding down the glass is something a hand does by
 * accident on the way to letting go.
 */
export const DISMISS_SWIPE_PX = 90;

/**
 * Whether two fingers travelling together mean "put this away".
 *
 * Down only. Up is left alone deliberately — there is nothing above full screen to go to, so
 * an upward swipe that did something would be a gesture nobody asked for.
 */
export function dismissIntent(dx: number, dy: number): boolean {
  if (!Number.isFinite(dx) || !Number.isFinite(dy)) return false;
  return dy >= DISMISS_SWIPE_PX && Math.abs(dx) <= dy;
}

/**
 * How much to enlarge the picture so it covers a differently shaped screen, given both
 * shapes as width divided by height. Always at least 1: filling never shrinks anything.
 */
export function fillScaleFor(videoRatio: number, frameRatio: number): number {
  if (!Number.isFinite(videoRatio) || !Number.isFinite(frameRatio)) return 1;
  if (videoRatio <= 0 || frameRatio <= 0) return 1;
  return Math.max(1, frameRatio / videoRatio, videoRatio / frameRatio);
}
